<?php
require dirname(__DIR__).'/includes/bootstrap.php'; $user=require_role('admin','receptionist'); $title=t('Patient queue'); $error=null;
$doctorId=(int)($_GET['doctor']??0); $doctor=one('SELECT * FROM doctors WHERE id=?',[$doctorId]);
if(!$doctor) { http_response_code(404); exit(t('Doctor not found.')); }
$date=(string)($_GET['date']??today()); if(!valid_date($date)) $date=today();
$_SESSION['walkin_keys'] ??= []; $_SESSION['walkin_keys']=array_filter($_SESSION['walkin_keys'],fn($t)=>$t>time()-7200);
if($_SERVER['REQUEST_METHOD']==='POST') {
    verify_csrf();
    try {
        if(($_POST['action']??'')==='status') {
            $target=one('SELECT id FROM appointments WHERE id=? AND doctor_id=? AND appointment_date=?',[(int)($_POST['appointment_id']??0),$doctorId,$date]);
            if(!$target) throw new DomainException(t('Appointment not found in this queue.'));
            change_status((int)$target['id'],(string)($_POST['status']??''),$doctorId); flash(t('Patient status updated.'));
        } elseif(($_POST['action']??'')==='walkin') {
            $key=(string)($_POST['submission_key']??'');
            if(!isset($_SESSION['walkin_keys'][$key])) throw new DomainException(t('The form has expired. Refresh and try again.'));
            $a=book_appointment($doctorId,$date,(string)($_POST['name']??''),(string)($_POST['phone']??''),(string)($_POST['reason']??''),$key,'walk-in',(int)$user['id']);
            flash(t('queue.booked',['token'=>$a['token_number'],'time'=>time_label($a['estimated_time'])]));
        } else throw new DomainException(t('Unknown action.'));
        redirect('reception/queue.php?doctor='.$doctorId.'&date='.$date);
    } catch(DomainException $e) { $error=$e->getMessage(); }
}
$s=schedule_for($doctorId,$date); $state=booking_state($doctorId,$date); $search=trim((string)($_GET['q']??''));
$patients=query('SELECT * FROM appointments WHERE doctor_id=? AND appointment_date=? AND (patient_name LIKE ? OR patient_phone LIKE ? OR CAST(token_number AS CHAR)=?) ORDER BY token_number',[$doctorId,$date,'%'.$search.'%','%'.$search.'%',$search])->fetchAll();
$counts=one("SELECT COUNT(*) total,COALESCE(SUM(status IN ('Booked','Arrived')),0) waiting,COALESCE(SUM(status='Completed'),0) completed,MAX(CASE WHEN status='In Consultation' THEN token_number END) serving FROM appointments WHERE doctor_id=? AND appointment_date=?",[$doctorId,$date]);
$key=bin2hex(random_bytes(32)); $_SESSION['walkin_keys'][$key]=time();
$transitions=['Booked'=>['Arrived','In Consultation','No-show','Cancelled'],'Arrived'=>['In Consultation','No-show','Cancelled'],'In Consultation'=>['Completed','Arrived'],'No-show'=>['Arrived','Cancelled'],'Completed'=>[],'Cancelled'=>[]];
require dirname(__DIR__).'/includes/header.php';
?>
<main id="main" class="container section"><a class="back-link" href="<?= e(url('reception/index.php?date='.$date)) ?>"><?= e(t('← All patient queues')) ?></a><div class="section-heading"><div><div class="eyebrow"><?= e(t($doctor['specialization'])) ?></div><h1><?= e($doctor['name']) ?></h1><p class="muted"><?= e($s ? t('queue.date_time',['date'=>date_label($date),'time'=>time_label($s['consultation_start'])]) : date_label($date)) ?></p></div><a class="btn btn-outline-primary" href="<?= e(url('reception/print.php?doctor='.$doctorId.'&date='.$date)) ?>" target="_blank" rel="noopener"><?= e(t('Print patient list ↗')) ?></a></div><?php if($error): ?><div class="alert alert-danger" role="alert"><?= e($error) ?></div><?php endif; ?><div class="queue-overview"><div class="now-serving"><span><?= e(t('NOW SERVING')) ?></span><strong><?= $counts['serving']?'#'.e($counts['serving']):'—' ?></strong></div><div><strong><?= e($counts['total']) ?></strong><span><?= e(t('Total bookings')) ?></span></div><div><strong><?= e($counts['waiting']) ?></strong><span><?= e(t('Waiting')) ?></span></div><div><strong><?= e($counts['completed']) ?></strong><span><?= e(t('Completed')) ?></span></div><div><span class="soft-tag"><?= e($state['label']) ?></span><small><?= e(t('queue.remaining',['count'=>$state['remaining']??0])) ?></small></div></div><form method="get" class="filter-bar"><input type="hidden" name="doctor" value="<?= $doctorId ?>"><label for="date" class="visually-hidden"><?= e(t('Appointment date')) ?></label><input id="date" type="date" name="date" class="form-control" value="<?= e($date) ?>" required><label for="q" class="visually-hidden"><?= e(t('Search patients')) ?></label><input id="q" name="q" type="search" class="form-control search-input" placeholder="<?= e(t('Search name, phone or token')) ?>" value="<?= e($search) ?>"><button class="btn btn-outline-primary"><?= e(t('Apply filters')) ?></button><a class="text-link" href="<?= e(url('reception/queue.php?doctor='.$doctorId.'&date='.$date)) ?>"><?= e(t('Refresh / clear')) ?></a></form><div class="panel"><div class="table-responsive"><table class="table queue-table align-middle"><thead><tr><th><?= e(t('Token')) ?></th><th><?= e(t('Patient')) ?></th><th><?= e(t('Phone')) ?></th><th><?= e(t('Estimated time')) ?></th><th><?= e(t('Status')) ?></th><th><?= e(t('Update status')) ?></th></tr></thead><tbody><?php foreach($patients as $p): ?><tr class="<?= $p['status']==='In Consultation'?'serving-row':'' ?>"><td><span class="table-token">#<?= e($p['token_number']) ?></span></td><td><strong><?= e($p['patient_name']) ?></strong><small class="d-block muted" dir="ltr"><?= e($p['reference']) ?></small><?php if($p['reason']): ?><details class="patient-note"><summary><?= e(t('Visit note')) ?></summary><?= e($p['reason']) ?></details><?php endif; ?></td><td dir="ltr"><?= e($p['patient_phone']) ?></td><td><?= e(time_label($p['estimated_time'])) ?></td><td><?= status_badge($p['status']) ?></td><td><?php if($transitions[$p['status']]): ?><form method="post" class="status-form"><?= csrf_field() ?><input type="hidden" name="action" value="status"><input type="hidden" name="appointment_id" value="<?= e($p['id']) ?>"><select name="status" class="form-select form-select-sm" aria-label="<?= e(t('queue.status_label',['token'=>$p['token_number']])) ?>"><?php foreach($transitions[$p['status']] as $status): ?><option value="<?= e($status) ?>"><?= e(t($status)) ?></option><?php endforeach; ?></select><button class="btn btn-outline-primary btn-sm"><?= e(t('Update')) ?></button></form><?php else: ?><span class="small muted"><?= e(t('Closed')) ?></span><?php endif; ?></td></tr><?php endforeach; ?><?php if(!$patients): ?><tr><td colspan="6" class="text-center py-5 muted"><?= e(t($search?'queue.no_matches':'queue.no_patients')) ?></td></tr><?php endif; ?></tbody></table></div><p class="small muted mb-0"><?= e(t('Tokens stay in booking order. A new token may fill a cancelled consultation position, so its estimated time can be earlier. No-show positions remain reserved; cancel to release one.')) ?></p></div><section class="panel mt-4"><h2><?= e(t('Add a walk-in patient')) ?></h2><p class="muted"><?= e(t('Walk-ins follow the same booking window, capacity and token rules.')) ?></p><?php if($state['open']): ?><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="walkin"><input type="hidden" name="submission_key" value="<?= e($key) ?>"><div class="row g-3 align-items-end"><div class="col-md-4"><label for="name" class="form-label"><?= e(t('Full name')) ?></label><input id="name" name="name" class="form-control" required maxlength="100" value="<?= e($_POST['name']??'') ?>"></div><div class="col-md-3"><label for="phone" class="form-label"><?= e(t('Mobile number')) ?></label><input id="phone" name="phone" type="tel" class="form-control" required maxlength="20" placeholder="03001234567" value="<?= e($_POST['phone']??'') ?>"></div><div class="col-md-3"><label for="reason" class="form-label"><?= e(t('Reason (optional)')) ?></label><input id="reason" name="reason" class="form-control" maxlength="500" value="<?= e($_POST['reason']??'') ?>"></div><div class="col-md-2"><button class="btn btn-primary w-100"><?= e(t('Add patient')) ?></button></div></div></form><?php else: ?><div class="notice"><?= e(t('queue.closed',['status'=>$state['label']])) ?></div><?php endif; ?></section></main><?php require dirname(__DIR__).'/includes/footer.php'; ?>
